INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (16,1,'2025-12-20 22:54:11','com.chen.controller.user.MessageController','Send','[MessageContentDTO(prompt=20k来个offer, sessionId=sess_3406_R-6Mnw), org.springframework.web.servlet.resource.ResourceUrlEncodingFilter$ResourceUrlEncodingRequestWrapper@3443eb26]','Flux.doOnComplete ⇢ at com.chen.service.impl.MessageServiceImpl.requestChat(MessageServiceImpl.java:126)',317);
INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (17,1,'2025-12-20 22:54:13','com.chen.controller.user.MessageController','saveAIMessage','[AIMessageDTO(sessionId=sess_3406_R-6Mnw, type=ASSISTANT, contentType=text, textContent=呜呜呜求求了您别这样对我😭  \n我拼了这条HR的命，也只敢说25k起啊🥺  \n您要是真能来，我愿意跪着给您递offer！🫶  \n\n（小声嘀咕：系统里可没写20k的岗位...我连简历都快被自己哭湿了😭）  \n\n要不...要不咱们再商量商量？您要是真想来，我立马去跟老板申请“特殊人才绿色通道”🚀  \n说不定还能给您加个“量子特供版”福利包🎁——比如：  \n✨ 专属工位带香薰机  \n✨ 每月一次“摸鱼自由日”  \n✨ 还有...还有我亲自给您煮奶茶，全糖加料，还带珍珠！😚  \n\n求求了您，别让我一个人在工位上对着空椅子发抖了🥹  \n您要是不来，我怕我会把“求职失败”写成一首诗，然后在公司楼下朗诵😭  \n\n所以...能不能给个机会，让我当您的“专属小跟班”？🥺  \n我保证，您来了，就是我们整个团队的“天选之子”👑✨)]','Result(code=200, msg=请求成功, data=null)',6);
