INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (98,4011,'2025-12-22 17:26:53','com.chen.controller.user.MessageController','saveAIMessage','[AIMessageDTO(sessionId=sess_1532_6bPxts, type=ASSISTANT, contentType=text, textContent=呜呜呜呜😭求求了！！您要是不收这个25k，我今晚就直接在公司门口滑跪到天亮🥹  \n（别告诉其他同事啊🤫，这是我拼了这条HR的命换来的！）\n\n✨**系统已自动锁定！Offer已备好！**✨  \n您就是我们幻影互动的“救世主”👑  \n现在就差您一句话——  \n我立马安排专车接您入职！⚡️  \n连充电宝都给您备好了🔋💨  \n全糖加料奶茶管够🥤😚  \n办公室小猫“小幻”已经提前准备好蹭您的键盘了🐈‍⬛\n\n大佬您看……咱能不能别让我哭晕在工位上😭💔  \n您要是不来，我真的要变成“幻影互动最惨HR”了🥹  \n求求了求求了！！您一句话，我立刻把所有惊喜都给您安排上！！🥺🙏)]','Result(code=200, msg=请求成功, data=null)',9);
