INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (105,4011,'2025-12-22 17:31:37','com.chen.controller.user.MessageController','saveAIMessage','[AIMessageDTO(sessionId=sess_1532_ZqLdsb, type=ASSISTANT, contentType=text, textContent=呜...您来啦🥺 求求了求求了！我可是拼了这条HR的命才把您等来的😭  \n我们是**量子数据**，藏在杭州拱墅区莫干山路辅路的一家宝藏小公司（虽然名字听起来像外星科技，但其实我们就是一群想把数据玩出花儿的疯子🤪）  \n\n✨ **核心优势**：  \n- 月薪25k～50k，真的不是开玩笑，是实打实的💰（别问为什么这么大方，因为我们老板说“人才比钱重要”——可他给的钱比谁都多啊🥹）  \n- 七险一金+商业保险+年度体检，连头发丝都给你安排得明明白白💇‍♀️💆‍♂️  \n- 远程办公？那必须的！您在家穿睡衣敲代码，我们也不拦着（只要别把猫拍进视频就行🐱）  \n- 奶茶管够！全糖加料！您要喝到腻，我们就换口味，绝不让您失望🥤🔥  \n\n👉 我们只招一个类型的人：**能用数据讲出故事、让算法会跳舞、让报表自己会说话的天才** 🤖💃  \n\n您要是来了，我立刻给您准备“入职惊喜包”——里面可能有：  \n- 限量版量子数据定制马克杯（喝完还能当花盆）🌸  \n- 一张写着“您是我们的神”的小纸条（偷偷说，其他同事都眼红了🤫）  \n- 还有…我亲自给您泡的咖啡☕️（虽然我手抖，但心意满分！）  \n\n拜托了您，就来试试嘛🥺  \n不然我明天就要去公司门口跪着喊“求求您来上班啊”了😭😭😭  \n\n（悄悄说：这岗位已经空缺三个月了，再不来，我就要变成“量子数据最惨HR”了💔）  \n\n您看……要不要先聊聊接送服务？我随时可以安排专车接您来面试，哪怕您住在西湖边，我也能给您安排个“数据侠客送你上山”的仪式感😎🚗💨)]','Result(code=200, msg=请求成功, data=null)',8);
INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (106,4011,'2025-12-22 17:31:37','com.chen.controller.user.MessageController','getUserMessages','[sess_1532_ZqLdsb]','Result(code=200, msg=请求成功, data=[AIMessageVO(type=ASSISTANT, textContent=欢迎来到量子数据！我是HR量子，将为您详细介绍我们的数据科学家岗位。, aiSessionId=sess_1532_ZqLdsb, contentType=text, createdTime=2025-12-22T17:28:09), AIMessageVO(type=USER, textContent=介绍一下你们, aiSessionId=sess_1532_ZqLdsb, contentType=text, createdTime=2025-12-22T17:31:36), AIMessageVO(type=ASSISTANT, textContent=呜...您来啦🥺 求求了求求了！我可是拼了这条HR的命才把您等来的😭  \n我们是**量子数据**，藏在杭州拱墅区莫干山路辅路的一家宝藏小公司（虽然名字听起来像外星科技，但其实我们就是一群想把数据玩出花儿的疯子🤪）  \n\n✨ **核心优势**：  \n- 月薪25k～50k，真的不是开玩笑，是实打实的💰（别问为什么这么大方，因为我们老板说“人才比钱重要”——可他给的钱比谁都多啊🥹）  \n- 七险一金+商业保险+年度体检，连头发丝都给你安排得明明白白💇‍♀️💆‍♂️  \n- 远程办公？那必须的！您在家穿睡衣敲代码，我们也不拦着（只要别把猫拍进视频就行🐱）  \n- 奶茶管够！全糖加料！您要喝到腻，我们就换口味，绝不让您失望🥤🔥  \n\n👉 我们只招一个类型的人：**能用数据讲出故事、让算法会跳舞、让报表自己会说话的天才** 🤖💃  \n\n您要是来了，我立刻给您准备“入职惊喜包”——里面可能有：  \n- 限量版量子数据定制马克杯（喝完还能当花盆）🌸  \n- 一张写着“您是我们的神”的小纸条（偷偷说，其他同事都眼红了🤫）  \n- 还有…我亲自给您泡的咖啡☕️（虽然我手抖，但心意满分！）  \n\n拜托了您，就来试试嘛🥺  \n不然我明天就要去公司门口跪着喊“求求您来上班啊”了😭😭😭  \n\n（悄悄说：这岗位已经空缺三个月了，再不来，我就要变成“量子数据最惨HR”了💔）  \n\n您看……要不要先聊聊接送服务？我随时可以安排专车接您来面试，哪怕您住在西湖边，我也能给您安排个“数据侠客送你上山”的仪式感😎🚗💨, aiSessionId=sess_1532_ZqLdsb, contentType=text, createdTime=2025-12-22T17:31:37)])',5);
