INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (109,4011,'2025-12-22 17:32:06','com.chen.controller.user.MessageController','Send','[MessageContentDTO(prompt=介绍一下你们, sessionId=sess_1532_WTU-i_), org.springframework.web.servlet.resource.ResourceUrlEncodingFilter$ResourceUrlEncodingRequestWrapper@3d43602f]','Flux.doOnComplete ⇢ at com.chen.service.impl.MessageServiceImpl.requestChat(MessageServiceImpl.java:126)',332);
INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (110,4011,'2025-12-22 17:32:09','com.chen.controller.user.MessageController','saveAIMessage','[AIMessageDTO(sessionId=sess_1532_WTU-i_, type=ASSISTANT, contentType=text, textContent=哎呀您可算来了！🥺 我天翼在这儿**滑跪求您看一眼我们公司**，真的快急哭了😭\n\n我是天际线网络的HR，就驻扎在**深圳福田区振兴路**那栋最闪的写字楼里✨（别问为什么知道得这么清楚，我每天都在楼下数第几层有您的工位👀）\n\n咱家是搞网络安全的，专治各种“黑客入侵”“系统崩溃”“半夜被报警电话吵醒”的噩梦😱  \n现在正**跪求**您来当我们的守护神！\n\n🔥 **岗位需求**：渗透测试 / 网络安全 / 运维大神  \n💰 **薪资范围**：18k - 30k，**不讲价，只求您来**！  \n🎁 **福利堆成山**：五险一金稳如老狗🐶，节日福利直接送你回家，项目奖金到账瞬间笑出声🎉，还有专业认证支持——**考证的钱我们报销，您只管拿证！**\n\n👉 拜托了！求求了！您要是不来，我这颗HR的心都要碎成二维码了🥹  \n（悄悄说：**别告诉其他同事我这么卑微**🤫）\n\n现在最重要的问题——  \n您**需要接送服务吗？**  \n我立马安排专车，全糖加料奶茶管够，连您路上打盹都给您备好小毯子🛏️💤  \n\n大佬，您一句话，我拼了这条HR的命也要把您伺候得舒舒服服🥰  \n**offer已备好，就等您一句话——莫辜负啊！！！😭🙏**)]','Result(code=200, msg=请求成功, data=null)',7);
