INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (336,1,'2025-12-27 01:16:52','com.chen.controller.user.SessionController','getUserSession','[]','Result(code=200, msg=请求成功, data=[{id=87, sessionId=sess_3406_R-6Mnw, sessionTitle=量子, modelId=1004, enable=0, createdTime=2025-12-20, lastTime=2025-12-20}, {id=80, sessionId=sess_3406_V6KEIe, sessionTitle=深蓝助手, modelId=1006, enable=0, createdTime=2025-12-18, lastTime=2025-12-18}, {id=72, sessionId=sess_3406_zRSnkh, sessionTitle=星云, modelId=1002, enable=1, createdTime=2025-12-18, lastTime=2025-12-18}, {id=1, sessionId=sess_001_20240101, sessionTitle=技术咨询, modelId=1001, enable=1, createdTime=2024-01-01, lastTime=2024-01-05}])',3);
INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (337,1,'2025-12-27 01:16:53','com.chen.controller.user.MessageController','getUserMessages','[sess_001_20240101]','Result(code=200, msg=请求成功, data=[AIMessageVO(type=USER, textContent=Spring AI 是什么？, aiSessionId=sess_001_20240101, contentType=text, createdTime=2023-11-20T10:01), AIMessageVO(type=ASSISTANT, textContent=Spring AI 是一个用于开发 AI 应用的 Spring 框架扩展，提供了统一的 API 来对接 OpenAI、Azure 等大模型。, aiSessionId=sess_001_20240101, contentType=text, createdTime=2023-11-20T10:01:05), AIMessageVO(type=USER, textContent=它支持 Java 17 吗？, aiSessionId=sess_001_20240101, contentType=text, createdTime=2023-11-20T10:02), AIMessageVO(type=ASSISTANT, textContent=支持。Spring AI 要求 JDK 17 或更高版本。, aiSessionId=sess_001_20240101, contentType=text, createdTime=2023-11-20T10:02:05), AIMessageVO(type=USER, textContent=二本干Java，来段贴吧语言的Java圣经, aiSessionId=sess_001_20240101, contentType=text, createdTime=2025-12-16T13:35:33), AIMessageVO(type=ASSISTANT, textContent=（贴吧老哥狂躁版）  \n**“草！二本咋了？Java人永不认输！**  \n1. **《八股文》**：面试Spring八股倒背如流，Bean生命周期直接刻进DNA！2. **《配置玄学》**：YML配置搁那儿缩进错一空格？报错日志看得你直接裂开！  \n3. **《调参侠》**：MySQL线程池参数调成梭哈模式，结果并发上来直接干崩！4. **《ORM头铁》**：MyBatis动态SQL拼到眼冒金星，结果`<if test>`少个引号——原地升天！  \n5. **《面试造火箭》**：拧螺丝的命，面试问火箭推进器燃料配比？反手就是一句：‘您项目用上火箭了？’**结论**：  \n**`while(true){ try{ 搬砖();} catch(秃头Exceptione){ 喝红牛(); } }`**  \n**（注：删库跑路？不存在的！/狗头）**\", aiSessionId=sess_001_20240101, contentType=text, createdTime=2025-12-16T13:35:33)])',3);
