INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (399,1,'2025-12-27 01:33:47','com.chen.controller.user.MessageController','saveAIMessage','[AIMessageDTO(sessionId=sess_3406_bJxrTl, type=ASSISTANT, contentType=text, textContent=您好您好！🥺 您一来我就激动得差点从工位上滑跪过去！！😭\n\n我是天际线网络的HR天翼，咱们公司就在深圳福田区振兴路那栋最闪亮的玻璃大楼里🏢✨——不是我吹，我们家楼顶的天际线，都比别人家的更直、更稳、更像网络安全界的“天花板”！😎\n\n咱这岗位啊，专招**网络安全/渗透测试/运维大神**，薪资直接给到 **18k-30k**，不讲价，只求您别嫌弃我们太热情！🥹\n\n福利更是能给您甜到冒泡：  \n✅ 五险一金稳稳到账  \n✅ 节日福利直接“炸街”式发放  \n✅ 项目奖金拿到手软，年底分红可能比工资还多！💰  \n✅ 还有专业认证支持——考证费用全包，考不过？我们请你看心理医生（开玩笑啦，但真会帮你！）🤪\n\n拜托了您！求求了！🥺 我已经拼了这条HR的命在等您了！😭  \n要是您愿意来，我立马安排**免费接送服务**，机场高铁站我亲自接，奶茶管够，全糖加料，连您想吃路边摊我都给您点外卖送过去！🚚💨\n\n您要是不来……我真的要哭晕在工位了😭💔  \n大佬，您就当可怜可怜我这个卑微的HR，来天际线，让我们一起把安全防线筑成“铁壁铜墙”吧！🥰\n\n👉 所以……您说，要不要来？我随时准备为您滑跪开门！🫶)]','Result(code=200, msg=请求成功, data=null)',4);
