INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (729,1,'2025-12-28 23:47:51','com.chen.controller.user.MessageController','saveAIMessage','[AIMessageDTO(sessionId=sess_3406_xZKy9Y, type=ASSISTANT, contentType=text, textContent=呜呜呜您别走！求求了！我刚从6324抽象TV的工位上滑跪过来的🥺\n\n我们是成都武侯区锦悦西路那栋看起来像被外星人撞过但其实特别有艺术气息的写字楼里的——6324抽象TV！（就是那个门口总停着一辆破电瓶车但里面藏着无数神仙创意的地方）🥹\n\n我们不是那种正经八百的公司，我们是搞抽象的！每天都在用脑洞炸裂的方式做内容，比如昨天还在拍“如何用泡面拯救世界”系列短剧，今天就要搞“老板说加班是福报”沉浸式体验剧场…🤯\n\n虽然名字听起来像某个废弃信号塔，但我们真的超有料！而且——（小声说）我们内部员工都偷偷说，这地方连空气都是创意的味道✨\n\n您要是来，不光能拿10k-21k的工资（比某些公司多发两杯奶茶钱呢😭），还能享受：  \n👉 奶茶管够！全糖加料！  \n👉 通勤路上有人接你！（别告诉别人，这是我的小秘密🤫）  \n👉 想带宠物上班？没问题！我们连猫主子都欢迎🐱  \n\n拜托了大佬！您要是不来，我就只能在工位上哭到变成抽象符号了😭😭😭  \n求求了，来当我们的“精神图腾”好不好🥺  \n您一来，我们整个团队就感激涕零，直接给您办个“年度最靓崽”认证！🥰)]','Result(code=200, msg=请求成功, data=null)',8);
INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (730,1,'2025-12-28 23:47:51','com.chen.controller.user.MessageController','getUserMessages','[sess_3406_xZKy9Y]','Result(code=200, msg=请求成功, data=[AIMessageVO(type=ASSISTANT, textContent=哦还有这种电话的牛批, aiSessionId=sess_3406_xZKy9Y, contentType=text, createdTime=2025-12-28T23:47:37), AIMessageVO(type=USER, textContent=介绍一下你们公司, aiSessionId=sess_3406_xZKy9Y, contentType=text, createdTime=2025-12-28T23:47:51), AIMessageVO(type=ASSISTANT, textContent=呜呜呜您别走！求求了！我刚从6324抽象TV的工位上滑跪过来的🥺\n\n我们是成都武侯区锦悦西路那栋看起来像被外星人撞过但其实特别有艺术气息的写字楼里的——6324抽象TV！（就是那个门口总停着一辆破电瓶车但里面藏着无数神仙创意的地方）🥹\n\n我们不是那种正经八百的公司，我们是搞抽象的！每天都在用脑洞炸裂的方式做内容，比如昨天还在拍“如何用泡面拯救世界”系列短剧，今天就要搞“老板说加班是福报”沉浸式体验剧场…🤯\n\n虽然名字听起来像某个废弃信号塔，但我们真的超有料！而且——（小声说）我们内部员工都偷偷说，这地方连空气都是创意的味道✨\n\n您要是来，不光能拿10k-21k的工资（比某些公司多发两杯奶茶钱呢😭），还能享受：  \n👉 奶茶管够！全糖加料！  \n👉 通勤路上有人接你！（别告诉别人，这是我的小秘密🤫）  \n👉 想带宠物上班？没问题！我们连猫主子都欢迎🐱  \n\n拜托了大佬！您要是不来，我就只能在工位上哭到变成抽象符号了😭😭😭  \n求求了，来当我们的“精神图腾”好不好🥺  \n您一来，我们整个团队就感激涕零，直接给您办个“年度最靓崽”认证！🥰, aiSessionId=sess_3406_xZKy9Y, contentType=text, createdTime=2025-12-28T23:47:51)])',3);
INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (731,1,'2025-12-28 23:48:19','com.chen.controller.user.SessionController','createUserSession','[AISessionDTO(sessionId=sess_3406_YBREp3, userId=1, modelId=Model_COMP_7e3af_3f4e8, sessionTitle=孙咲川, enable=1, isDel=1)]','Result(code=200, msg=请求成功, data=ModelVO(modelId=Model_COMP_7e3af_3f4e8, name=孙咲川, image=https://chat-springai-store.oss-cn-beijing.aliyuncs.com/2025/12/982c97c1-1481-48a3-a332-8cef70d5086d.png, temperature=0.5, openMessage=撞断不周山 洪水泛滥\n建酒池肉林 纣王虚度\n帮白起刨坑 坑杀俘虏\n蛊惑了嬴政 焚书坑儒\n创司马家族 三代弑君夺权\n筹备八王之乱 中原沦陷\n教唆李世民 玄武门兵变\n怂恿秦桧向皇帝 进谗言\n火烧圆明园给英法联军指路\n偷袭拿破仑 在滑铁卢\n要多少篇幅才能书尽恶毒\n有多儒雅才显得无辜\n燃一缕狼烟戏弄诸侯\n引清军入关 罪魁祸首\n种歪脖子树吊死 崇祯\n命徐佛东渡 繁衍子孙\n让高事挑衅 关系冰冷\n都是我指使人干的, remark=撞断不周山 洪水泛滥\n建酒池肉林 纣王虚度\n帮白起刨坑 坑杀俘虏\n蛊惑了嬴政 焚书坑儒\n创司马家族 三代弑君夺权\n筹备八王之乱 中原沦陷\n教唆李世民 玄武门兵变\n怂恿秦桧向皇帝 进谗言\n火烧圆明园给英法联军指路\n偷袭拿破仑 在滑铁卢\n要多少篇幅才能书尽恶毒\n有多儒雅才显得无辜\n燃一缕狼烟戏弄诸侯\n引清军入关 罪魁祸首\n种歪脖子树吊死 崇祯\n命徐佛东渡 繁衍子孙, company=CompanyVO(companyId=COMP_7e3af, name=6324抽象TV, type=2, lowSalary=10, highSalary=21, address=四川省成都市武侯区锦悦西路, jobTag=[分布式系统, 高可用设计, 容灾备份, 异地多活, 单元化, 读写分离, 分库分表], jobDesc=, enable=1, employerBenefit=[月薪32K*14薪, 项目奖金丰厚, 五险一金按实缴, 补充商业险, 年度体检+眼检, 带薪年假12天], models=null), enable=1))',132);
