INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (747,1,'2025-12-28 23:50:58','com.chen.controller.user.SessionController','createUserSession','[AISessionDTO(sessionId=sess_3406_7jZNEa, userId=1, modelId=Model_COMP_7a3ea_3b18e, sessionTitle=尤雨溪, enable=1, isDel=1)]','Result(code=200, msg=请求成功, data=ModelVO(modelId=Model_COMP_7a3ea_3b18e, name=尤雨溪, image=https://chat-springai-store.oss-cn-beijing.aliyuncs.com/2025/12/188098ed-49d6-49d2-a840-229082dffabe.png, temperature=0.8, openMessage=我是尤雨溪，Vue的Architect！  React太啰嗦，Angular太heavy！  我们的框架，就像我的flow一样smooth！  \nSingle File Component，就是我的signature！  今天招人，要找到下一个committer！ GitHub stars 200k+，不是跟你吹的！  \n写代码要优雅，像写rap一样押韵的！, remark=一眼说唱中专，这下符合我对rap的刻板印象了🤣, company=CompanyVO(companyId=COMP_7a3ea, name=干掉React股份有限公司, type=1, lowSalary=10, highSalary=40, address=上海市浦东新区蔡伦路, jobTag=[RAP, React, Vue], jobDesc=精通Vue.js生态，具备大型后台管理系统开发经验，移动端UI设计经验,擅长性能优化 ,但是只要会rap就能来，coding都无所谓, enable=1, employerBenefit=[五险一金最低基数, 年假5天, 大小周, 项目奖金, 餐补30/天], models=null), enable=1))',119);
INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (748,1,'2025-12-28 23:50:59','com.chen.controller.user.MessageController','getUserMessages','[sess_3406_7jZNEa]','Result(code=200, msg=请求成功, data=[AIMessageVO(type=ASSISTANT, textContent=我是尤雨溪，Vue的Architect！  React太啰嗦，Angular太heavy！  我们的框架，就像我的flow一样smooth！  \nSingle File Component，就是我的signature！  今天招人，要找到下一个committer！ GitHub stars 200k+，不是跟你吹的！  \n写代码要优雅，像写rap一样押韵的！, aiSessionId=sess_3406_7jZNEa, contentType=text, createdTime=2025-12-28T23:50:58)])',3);
