INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (751,1,'2025-12-28 23:51:29','com.chen.controller.user.ModelController','queryModelWithCompany','[0]','Result(code=200, msg=请求成功, data=ModelVO(modelId=0, name=, image=https://chat-springai-store.oss-cn-beijing.aliyuncs.com/2025/12/20251228010351_45_226.jpg, temperature=null, openMessage=null, remark=默认模型，默认无会话显示, company=null, enable=1))',2);
INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (752,1,'2025-12-28 23:51:29','com.chen.controller.user.MessageController','getUserMessages','[default_session]','Result(code=200, msg=请求成功, data=[AIMessageVO(type=USER, textContent=您好，我是蚌埠学院27届的XXX,这是我的简历\n..., aiSessionId=default_session, contentType=text, createdTime=2023-11-20T10:00), AIMessageVO(type=ASSISTANT, textContent=蚌埠学院？我咋没听说过，中专还是技校啊？, aiSessionId=default_session, contentType=text, createdTime=2025-12-28T00:18:21), AIMessageVO(type=USER, textContent=\r\n你是不是**求职**的时候被拷打麻了？趾高气扬的hr谁给他们的**底气**?\r\n---\r\n1. 民办学院本也敢投我们？你简历怎么过初筛的？\r\n2. 你只是个普通学院本啊？我们这边基本都是985硕士起步的，你这学历...\r\n3. 你之前的薪资是15k？在我们这只能给8k，年轻人要多学东西\r\n4. 我们996是常态，能接受吗？年轻人就该多奋斗，要把公司当家一样对待😅\r\n5. 试用期没五险一金，转正后补缴，行业都这样，你不干有的是人干\r\n6. 现在大环境不好，有offer就不错了，好好考虑\r\n7. 不会微服务？单体架构经验在我们这没用\r\n8. 上来就问造火箭的,spring源码手撕红黑树\r\n---\r\n但是现在不一样了，在这里 一切决定权在你手上，现在，深呼吸，点击\"开启新会话\"，然后**让他们见识一下，什么叫做降维打击**。😎, aiSessionId=default_session, contentType=text, createdTime=2025-12-28T00:51:13)])',2);
INSERT INTO `tb_ai_log` (`id`, `operate_id`, `operate_time`, `class_name`, `method_name`, `method_params`, `return_value`, `cost_time`) VALUES (753,1,'2025-12-28 23:52:28','com.chen.controller.user.UserController','getUserInfo','[]','Result(code=200, msg=请求成功, data=UserVO(id=1, nickName=chen, gender=1, email=3406339653@qq.com, image=https://chat-springai-store.oss-cn-beijing.aliyuncs.com/2025/12/20251227020827_43_226.jpg, birthday=2025-12-09, points=null, enable=1, registerTime=2025-12-28T00:09:11))',3);
